use carrick_guest_mem::{DeferredAnonymousState, MemoryError};

pub(super) fn scrub_unless_pristine(
    enabled: bool,
    deferred: Option<&DeferredAnonymousState>,
    address: u64,
    len: usize,
    scrub: impl FnOnce() -> Result<(), MemoryError>,
) -> Result<(), MemoryError> {
    // This is positive exact-MM provenance, not a missing-translation test.
    // Materialization holds the provenance lock through publication and removes
    // pristine coverage at commit. The query either observes pristine zeroes or
    // acquires after publication and falls through to authenticated maintenance.
    // A write published after a successful query is ordered after this no-op
    // scrub; no state is retained across calls or inferred for adjacent ranges.
    if enabled
        && deferred
            .is_some_and(|state| state.covers_pristine(carrick_guest_mem::GuestVa(address), len))
    {
        return Ok(());
    }
    scrub()
}

#[cfg(test)]
mod tests {
    use super::*;
    use carrick_conformance_contract::{
        Completeness, ContractId, ContractObservation, ContractRegistry, ExecutionLayer,
        SemanticAssertion, WorkMetric, WorkSnapshot, evaluate,
    };
    use carrick_guest_mem::GuestVa;
    use std::hash::{Hash, Hasher};

    #[test]
    fn pristine_scrub_contract() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .unwrap()
            .parent()
            .unwrap();
        let registry = ContractRegistry::load(root).unwrap();
        let mut source = std::collections::hash_map::DefaultHasher::new();
        include_str!("pristine_scrub.rs").hash(&mut source);
        include_str!("engine.rs").hash(&mut source);
        let mut observations = Vec::new();
        for scale in [1_u64, 8, 32, 128] {
            let state = DeferredAnonymousState::new();
            let len = scale as usize * 4096;
            state.reserve_fresh(GuestVa(0x1000), len).unwrap();
            let mut calls = 0;
            scrub_unless_pristine(true, Some(&state), 0x1000, len, || {
                calls += 1;
                Ok(())
            })
            .unwrap();
            assert!(state.covers_pristine(GuestVa(0x1000), len));
            let mut work = WorkSnapshot::new();
            work.insert(WorkMetric::HostBackendCalls, calls).unwrap();
            observations.push(ContractObservation {
                contract_id: ContractId::new("kernel.mm.pristine-scrub").unwrap(),
                layer: ExecutionLayer::VmFree,
                implementation_revision: format!("source-default-hasher:{:016x}", source.finish()),
                fixture_identity: "unit:pristine-scrub".into(),
                scale,
                semantic_assertions: vec![SemanticAssertion::pass("pristine_provenance_preserved")],
                work: Some(work),
                timing: None,
                completeness: Completeness::Complete,
            });
        }
        println!("{observations:#?}");
        evaluate(
            registry.require("kernel.mm.pristine-scrub").unwrap(),
            &observations,
        )
        .unwrap();
    }

    #[test]
    fn scrub_requires_complete_pristine_authority_and_preserves_errors() {
        let state = DeferredAnonymousState::new();
        state.reserve_fresh(GuestVa(0x1000), 4096).unwrap();
        for (enabled, authority, address, len) in [
            (false, Some(&state), 0x1000, 4096),
            (true, None, 0x1000, 4096),
            (true, Some(&state), 0x1000, 8192),
            (true, Some(&state), 0x2000, 4096),
            (true, Some(&state), u64::MAX - 4095, 8192),
        ] {
            let mut calls = 0;
            let result = scrub_unless_pristine(enabled, authority, address, len, || {
                calls += 1;
                Err(MemoryError::OutOfBounds {
                    address,
                    length: len,
                })
            });
            assert!(matches!(result, Err(MemoryError::OutOfBounds { .. })));
            assert_eq!(calls, 1);
        }
    }
}

