        let snapshot = self
            .vm
            .save_guest_state(&mut self.vcpu)
            .map_err(|error| TrapError::Hypervisor(format!("save AArch64 guest state: {error}")))?;
        Ok(GuestCpuState::from_aarch64_v1(
            aarch64_task_state_from_snapshot(
                &snapshot,
                self.pending_resume_pc,
